        JSONObject vwap=e.addIndicator("session-vwap","vwap",new JSONObject().put("calendar",CALENDAR).put("deviation",2));out.put("session-vwap",vwap.getJSONArray("outputs"));
        e.registerIndicatorModule("aster.volume-direction",1);JSONObject pressure=e.addIndicator("pressure","aster.volume-direction@1/pressure",new JSONObject().put("factor",1).put("shift",0));out.put("pressure",pressure.getJSONArray("outputs"));
